export const blogArticlesHtml: Record<string, string> = {
  "sonicdrop": "<p>\n                    <strong>SonicDrop</strong> is an open-source, air-gapped data transfer protocol and browser-based workstation engineered to transmit text, cryptographic keys, and sensitive payloads between commodity laptops and smartphones over <strong>near-inaudible ultrasonic sound waves</strong>. Operating with <strong>zero Wi-Fi, zero Bluetooth, zero cellular connection, and zero physical cables</strong>, SonicDrop leverages high-performance C++ digital signal processing (DSP) compiled to <strong>WebAssembly</strong>, 16-FSK modulation, Reed-Solomon forward error correction, and standard browser Web Audio APIs.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/sonicdrop_dashboard.png\" alt=\"SonicDrop Air-Gapped Ultrasonic Data Transfer Landing Page and Acoustic Link Simulation\" class=\"article-image\" />\n                </div>\n\n                <h2>The Premise: Breaking the RF Security Model</h2>\n                <p>\n                    Modern wireless communication protocols\u2014Wi-Fi, Bluetooth, NFC, and Ultra-Wideband (UWB)\u2014fundamentally rely on radio frequency (RF) electromagnetic radiation. While fast and ubiquitous, RF transceivers introduce severe security and operational vulnerabilities in high-security environments:\n                </p>\n                <ul>\n                    <li><strong>Electromagnetic Radiation & Wall Penetration:</strong> RF signals radiate in all directions and penetrate standard drywall, glass, and partitions. An eavesdropper with a directional antenna or Software-Defined Radio (SDR) can capture packets from outside a room or building.</li>\n                    <li><strong>Attack Surface & Handshake Vulnerabilities:</strong> Complex wireless stacks suffer from firmware exploits, deauthentication injection attacks, downgrade attacks, and pairing vulnerabilities (e.g., BlueBorne, BrakTooth, KRACK).</li>\n                    <li><strong>Device Pairing Friction & Hardware Lock-In:</strong> Protocols like Apple AirDrop mandate proprietary hardware and Bluetooth/Wi-Fi handshakes. Cross-platform sharing between iOS, Android, Linux, and Windows is fragmented and requires third-party cloud servers or shared local subnets.</li>\n                    <li><strong>Strict Air-Gap Regulations:</strong> In classified environments such as <strong>SCIFs (Sensitive Compartmented Information Facilities)</strong>, nuclear facilities, and cold-storage cryptocurrency vaults, RF transceivers and USB flash drives are strictly forbidden to eliminate malware exfiltration and covert radio transmitters.</li>\n                </ul>\n                <p>\n                    <strong>SonicDrop inverts this paradigm by turning ambient room air into the physical transmission medium.</strong> Sound waves travel through the air at approximately 343 m/s, strictly attenuate at solid walls, generate exactly <strong>0 dBm of electromagnetic radiation</strong>, and require no pairing, PINs, or specialized RF hardware.\n                </p>\n\n                <h2>End-to-End Acoustic Transport Pipeline</h2>\n                <p>\n                    The physical journey of a packet in SonicDrop spans digital encoding, acoustic modulation, acoustic wave propagation, Goertzel bandpass filtering, clock recovery, and hardware stream termination:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"max-width: 680px; margin: 1rem auto; padding: 1rem; background: #09090b;\">\n                    <div class=\"mermaid\" style=\"width: 100%; max-width: 100%; overflow: hidden;\">\nflowchart TD\n    subgraph TX [\"1. Transmitter\"]\n        direction LR\n        P[\"Payload\"] --> ENC[\"CRC-32 + RS(32, 24)\"] --> MOD[\"16-FSK Modulation\"] --> SPK[\"Speaker Transducer\"]\n    end\n\n    TX ==>|\"Acoustic Air-Gap (~343 m/s \u00b7 0 dBm RF)\"| RX\n\n    subgraph RX [\"2. Receiver\"]\n        direction LR\n        MIC[\"Microphone (48 kHz)\"] --> DSP[\"Goertzel DSP & Sync\"] --> DEC[\"FEC Decode & CRC\"] --> OUT[\"Verified Payload\"]\n    end\n                    </div>\n                </div>\n\n                <h2>Acoustic Physical Layer (PHY) &amp; 16-FSK Modulation</h2>\n                <p>\n                    SonicDrop transmits data using <strong>16-FSK (Multi-Frequency Shift Keying)</strong> across 16 orthogonal ultrasonic frequency bins placed between <strong>18,500 Hz and 20,000 Hz</strong>:\n                </p>\n                <ul>\n                    <li><strong>Why 18.5 kHz \u2013 20.0 kHz?</strong> The upper threshold of adult human hearing typically degrades beyond 16\u201317 kHz due to presbycusis. Positioning our carrier band between 18.5 kHz and 20.0 kHz renders transmissions near-inaudible to human ears in shared rooms.</li>\n                    <li><strong>Nyquist Sampling Headroom:</strong> Standard commodity device audio codecs record and play back at 44.1 kHz or 48.0 kHz. By capping our upper frequency bin at 20.0 kHz, the carrier fits comfortably below the 24.0 kHz Nyquist limit of 48 kHz ADCs, avoiding aliasing distortion.</li>\n                    <li><strong>Dual-Tone Synchronization Preamble:</strong> Before any payload bytes are emitted, SonicDrop broadcasts a Linear Frequency Modulated (LFM) chirp preamble. This distinct frequency sweep allows the receiver's Goertzel detectors to lock onto symbol boundaries with sub-millisecond precision.</li>\n                    <li><strong>15ms Soft-Taper Window Envelope:</strong> Abrupt transitions in audio waveforms produce audible mechanical \"clicks\" and wideband harmonic pops in commodity speaker cones. SonicDrop shapes each frequency burst with a 15ms raised-cosine taper, ensuring seamless acoustic ramp-up and ramp-down.</li>\n                </ul>\n\n                <h2>Dual Transmission Profiles: Stealth vs. Audible Modem</h2>\n                <p>\n                    Depending on the operating environment, users can toggle between two distinct acoustic physical layers:\n                </p>\n                <ul>\n                    <li><strong>Ultrasonic Stealth Mode (18.5 \u2013 20.0 kHz):</strong> Near-inaudible transmission engineered for public coffee shops, shared offices, and quiet indoor environments. Payloads cross the room silently.</li>\n                    <li><strong>Audible Acoustic Modem Mode (1.6 \u2013 3.1 kHz):</strong> Retro sci-fi acoustic modem chirps reminiscent of 1980s Bell 202 and dial-up modems. Highly resilient against severe background acoustic noise, physical distance, and ideal for audio verification and classroom demonstrations.</li>\n                </ul>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/sonicdrop-transmitter.png\" alt=\"SonicDrop Ultrasonic Transmitter Workstation with Payload Selection and Live Spectrogram\" class=\"article-image\" />\n                </div>\n\n                <h2>WebAssembly DSP Engine: Georgi Gerganov's ggwave</h2>\n                <p>\n                    Executing real-time digital signal processing in JavaScript introduces garbage collection pauses and JIT deoptimizations that destroy sample-accurate acoustic decoding. SonicDrop solves this by compiling Georgi Gerganov's high-performance C++ <code>ggwave</code> DSP library to <strong>WebAssembly (WASM)</strong>.\n                </p>\n                <p>\n                    Rather than computing a computationally intensive 2048-point Fast Fourier Transform (FFT) across all frequencies on every audio chunk, the WebAssembly engine utilizes <strong>Goertzel algorithms</strong>:\n                </p>\n                <ul>\n                    <li><strong>Targeted Frequency Evaluation:</strong> The Goertzel algorithm computes discrete Fourier transform terms specifically for our 16 known orthogonal carrier bins with $O(N)$ arithmetic complexity, dramatically slashing CPU and battery consumption.</li>\n                    <li><strong>Sample-Clock Drift Compensation:</strong> Commodity consumer hardware clocks drift: an iPhone crystal oscillator and a ThinkPad sound card never tick at precisely 48,000.00 Hz. The WASM engine performs dynamic phase tracking to reconstruct symbol timing on the fly.</li>\n                </ul>\n\n                <h2>Error Correction: Reed-Solomon RS(32, 24) &amp; IEEE CRC-32</h2>\n                <p>\n                    Physical air is a harsh, non-deterministic communication channel subject to multipath acoustic reflections, furniture echo, ambient air turbulence, and sudden transient room noise (e.g., keyboard clicks or coughing).\n                </p>\n                <p>\n                    SonicDrop defends against acoustic dropouts using a dual-layered error control pipeline:\n                </p>\n                <ul>\n                    <li><strong>Reed-Solomon RS(32, 24) Forward Error Correction:</strong> Every 24 bytes of user payload are encoded into a 32-byte codeword block with 8 Galois Field $GF(2^8)$ parity symbols. This mathematical redundancy enables the receiver to reconstruct up to <strong>4 completely destroyed symbol errors</strong> or <strong>8 known symbol erasures</strong> per block without requiring retransmission.</li>\n                    <li><strong>Hardware-Grade IEEE 802.3 CRC-32 Verification:</strong> Before data leaves the transmitter, a 32-bit cyclic redundancy check polynomial is computed across the raw payload. Upon reception and Reed-Solomon correction, the receiver validates the CRC checksum. If even a single bit is corrupt, the payload is rejected\u2014guaranteeing 100% bit-for-bit fidelity for sensitive cryptographic secrets.</li>\n                </ul>\n\n                <h2>Real-Time 60 FPS HTML5 Canvas Waterfall Spectrogram</h2>\n                <p>\n                    To provide immediate feedback during air-gap alignment, SonicDrop features a hardware-accelerated 60 FPS HTML5 Canvas waterfall spectrogram:\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/sonicdrop_receiver.png\" alt=\"SonicDrop Ultrasonic Receiver with Real-Time Waterfall Spectrogram and Auto-Stop Status\" class=\"article-image\" />\n                </div>\n\n                <p>\n                    The receiver feeds the incoming microphone PCM stream through a Web Audio <code>AnalyserNode</code> configured with an FFT size of 2048. SonicDrop slices the high-frequency ultrasonic region (18.5 \u2013 20.0 kHz), maps energy intensities to a high-contrast plasma color ramp, and scrolls the spectrogram history vertically. Users can visually observe incoming symbol chirps, ambient acoustic noise floors, and real-time <strong>Signal-to-Noise Ratio (SNR in dB)</strong> telemetry.\n                </p>\n\n                <h2>Zero-Trust Privacy &amp; Receiver Auto-Stop</h2>\n                <p>\n                    In modern web security, persistent microphone recording represents an unacceptable privacy hazard. Operating systems prominently display recording indicators (such as the orange dot in macOS and iOS or status bar notifications in Android), leaving users uneasy.\n                </p>\n                <p>\n                    SonicDrop implements an intelligent <strong>Receiver Auto-Stop</strong> architectural pattern:\n                </p>\n                <ul>\n                    <li>The moment a packet passes CRC-32 validation and Reed-Solomon decoding, SonicDrop immediately invokes <code>MediaStreamTrack.stop()</code> on all active microphone hardware tracks.</li>\n                    <li>The browser recording indicator immediately disappears from the OS menu bar.</li>\n                    <li>Audio processing threads terminate, reducing CPU overhead and preserving device battery.</li>\n                    <li>A single tap on <em>\"Listen for Next Message\"</em> re-arms the hardware receiver when the user is ready.</li>\n                </ul>\n\n                <h2>Protocol Comparison: Ultrasonic Air-Gap vs. RF Transports</h2>\n                <p>\n                    The following matrix illustrates how SonicDrop's acoustic air-gap protocol compares against traditional wireless protocols:\n                </p>\n\n                <div class=\"table-wrapper\" style=\"overflow-x: auto; margin: 1rem 0; border: 1px solid var(--border); border-radius: 10px; background: #09090b;\">\n                    <table style=\"width: 100%; border-collapse: collapse; font-size: 0.9rem; text-align: left;\">\n                        <thead>\n                            <tr style=\"border-bottom: 1px solid var(--border); background: rgba(255, 255, 255, 0.03);\">\n                                <th style=\"padding: 12px 16px; color: #ffffff;\">Capability</th>\n                                <th style=\"padding: 12px 16px; color: #00d2ff;\">SonicDrop (Ultrasonic)</th>\n                                <th style=\"padding: 12px 16px; color: #a1a1aa;\">Bluetooth 5.x</th>\n                                <th style=\"padding: 12px 16px; color: #a1a1aa;\">Wi-Fi Direct</th>\n                                <th style=\"padding: 12px 16px; color: #a1a1aa;\">Apple AirDrop</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">RF Signature / Emission</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">0 dBm (Zero RF)</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">10 \u2013 20 dBm</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">20 \u2013 30 dBm</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">10 \u2013 25 dBm</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">Pre-Pairing / PIN Handshake</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">None (Instant Drop)</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Required</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Required</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Required (iCloud/BT)</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">RF Sniffer / SDR Eavesdropping</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">100% Immune</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Vulnerable</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Vulnerable</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Vulnerable</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">SCIF / Defense Compliance</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">Compliant (Air-Gapped)</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Strictly Forbidden</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Strictly Forbidden</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Strictly Forbidden</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">Operating Mode</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">100% Offline (Airplane Mode)</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Requires Radio On</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Requires Radio On</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Requires Radio On</td>\n                            </tr>\n                            <tr>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #ffffff;\">Platform Support</td>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">Universal Web Audio</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">OS Stacks Differ</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Fragmented Drivers</td>\n                                <td style=\"padding: 12px 16px; color: #f87171;\">Apple Hardware Only</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <h2>Mission-Critical Use Cases</h2>\n                <p>\n                    SonicDrop addresses high-stakes security workflows where conventional networking is either prohibited or inherently unsafe:\n                </p>\n                <ul>\n                    <li><strong>Cold Storage &amp; Cryptocurrency Seed Phrases:</strong> Safely beam BIP-39 mnemonic recovery words, private keys, or offline-signed transaction hexes between air-gapped cold laptops and internet-connected devices without ever attaching a vulnerable USB thumb drive.</li>\n                    <li><strong>SCIF &amp; Classified Defense Facilities:</strong> Transfer mission coordinates, cryptographic hashes, and configuration dumps across workstations in TEMPEST-rated rooms where Wi-Fi, Bluetooth, cellular radios, and physical flash media are strictly banned.</li>\n                    <li><strong>Ephemeral Credentials &amp; TOTP Secrets:</strong> Pass sensitive one-time passwords, temporary SSH access keys, and production API tokens without leaving searchable audit logs on corporate Slack channels or intermediate cloud proxy logs.</li>\n                    <li><strong>Disaster Recovery &amp; Off-Grid Mesh Drop:</strong> Establish immediate peer-to-peer communications and emergency contact drops during telecommunications failures, power grid collapses, or in remote wilderness expeditions with Airplane Mode locked.</li>\n                </ul>\n\n                <h2>100% Offline Progressive Web App (PWA)</h2>\n                <p>\n                    SonicDrop is built as a standalone Progressive Web App. Through aggressive Service Worker caching, the entire C++ WebAssembly DSP bundle, acoustic modulation routines, and spectrogram shaders are permanently cached locally.\n                </p>\n                <p>\n                    Users can disconnect all network adapters, engage Airplane Mode on both sender and receiver devices, open the PWA from their desktop or home screen, and transfer data with complete physical sovereignty.\n                </p>\n\n                <h2>Technologies Used</h2>\n                <div class=\"article-tech-row\">\n                    <span class=\"article-tag\">C++ (ggwave)</span>\n                    <span class=\"article-tag\">WebAssembly (WASM)</span>\n                    <span class=\"article-tag\">TypeScript</span>\n                    <span class=\"article-tag\">React 18</span>\n                    <span class=\"article-tag\">Web Audio API</span>\n                    <span class=\"article-tag\">Reed-Solomon RS(32, 24)</span>\n                    <span class=\"article-tag\">IEEE 802.3 CRC-32</span>\n                    <span class=\"article-tag\">HTML5 Canvas (60 FPS)</span>\n                    <span class=\"article-tag\">Tailwind CSS</span>\n                    <span class=\"article-tag\">Vite &amp; PWA</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap;\">\n                    <a href=\"https://sonic-drop.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\">\n                        Open Live App \u2197\n                    </a>\n                    <a href=\"https://github.com/Krishnanand-10/SonicDrop\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                </footer>",
  "chronos": "<p>\n                    <strong>Chronos</strong> is a real-time, low-overhead OS telemetry engine and interactive terminal dashboard engineered from first principles in <strong>TypeScript</strong>. Powered by <strong>Ink</strong> (React for CLI runtimes), Chronos delivers high-frequency per-core CPU tick calculations, memory pressure monitoring, live network and disk I/O throughput tracking, deep TCP socket state analysis, and an interactive process manager with continuous rolling-window scrolling\u2014all while keeping garbage collection pauses near zero.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/chronos_dashboard.png\" alt=\"Chronos Tab 1 Dashboard Overview showing 16 Cores CPU grid, RAM & Swap Memory Pressure, and Network/Disk/Socket I/O matrix\" class=\"article-image\" />\n                </div>\n\n                <h2>The Motivation: Why Build a Custom Terminal Telemetry Engine?</h2>\n                <p>\n                    System monitoring tools have evolved down two contrasting paths: classic C/C++ utilities like <code>htop</code> and <code>btop</code>, or heavyweight Electron and web-based dashboards. When developers want custom telemetry within automated terminal pipelines or modern cross-platform Node.js environments, standard tools pose distinct challenges:\n                </p>\n                <ul>\n                    <li><strong>Garbage Collection Pauses in Node.js:</strong> Polling 16 or 32 CPU cores alongside disk, network, and process tables every 50ms to 250ms typically generates thousands of transient JavaScript objects per second. In standard Node runtimes, this causes periodic V8 Major GC pauses (Stop-the-World), introducing micro-stutters and artificial CPU spikes.</li>\n                    <li><strong>Lack of Fine-Grained Hardware Sympathy:</strong> High-level system information wrappers often fail to calculate accurate delta throughput on Windows when interface names have spaces or virtual adapters are present.</li>\n                    <li><strong>Terminal Rendering Overhead:</strong> Redrawing full terminal screens at high frequencies often results in screen tearing, ANSI cursor jitter, and ugly prompt remnants after exit.</li>\n                </ul>\n                <p>\n                    Chronos was engineered from the ground up to solve these problems by marrying <strong>zero-allocation typed array ring buffers</strong> with a <strong>decoupled multi-tiered sampling loop</strong> and <strong>atomic terminal frame batching</strong>.\n                </p>\n\n                <h2>System Architecture: Decoupled Multi-Tier Telemetry Engine</h2>\n                <p>\n                    To maintain smooth terminal interactivity without bottlenecking the event loop, Chronos decouples hardware metric acquisition into three distinct sampling tiers, feeding fixed-size typed ring buffers that are batch-consumed by the Ink presentation layer:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1rem; background: #09090b;\">\n                    <div class=\"mermaid\" style=\"width: 100%; max-width: 100%; overflow: hidden;\">\nflowchart TD\n    subgraph OS [\"1. Operating System &amp; Hardware Counters\"]\n        CPU_TICKS[\"Per-Core CPU Ticks (os.cpus)\"]\n        MEM_COUNTERS[\"Memory &amp; Swap Pressure (os.mem / si.mem)\"]\n        NET_IO[\"Network Counters (netstat -e / si.networkStats)\"]\n        DISK_IO[\"Disk I/O Throughput (si.disksIO)\"]\n        SOCKETS[\"TCP Socket Table (si.networkConnections)\"]\n        PROCS[\"Process Table &amp; Memory Maps (si.processes)\"]\n    end\n\n    subgraph ENGINE [\"2. Telemetry Ingestion Engine (Sampler.ts)\"]\n        T1[\"Tier 1: 50ms High-Frequency Fast Loop<br/>(CPU Ticks Delta &amp; RAM)\"]\n        T2[\"Tier 2: 250ms I/O &amp; Socket Sampling<br/>(Net Rx/Tx Deltas, Disk Throughput, TCP States)\"]\n        T3[\"Tier 3: 1000ms Process Inspection Loop<br/>(PID, %CPU, %MEM, RSS/VSZ, State)\"]\n    end\n\n    subgraph BUFFERS [\"3. Zero-GC Circular Memory Layer (RingBuffer.ts)\"]\n        RB_CPU_AVG[\"Float64Array: CPU Average Buffer\"]\n        RB_CORES[\"Float64Array[]: Per-Core Ring Buffers (16 Cores)\"]\n        RB_MEM[\"Float64Array: Memory Usage % Buffer\"]\n        RB_NET[\"Float64Array: Network Rx/Tx Buffers\"]\n        RB_DISK[\"Float64Array: Disk Read/Write Buffers\"]\n    end\n\n    subgraph UI [\"4. Terminal User Interface (Ink / React)\"]\n        SNAP[\"System Snapshot (100ms Batched Throttle)\"]\n        VIEW1[\"View 1: Overview Dashboard<br/>(Compact 2-Col CPU Grid + Memory + 3-Col I/O)\"]\n        VIEW2[\"View 2: Process Inspector<br/>(Rolling Window Smooth Scroll + Memory Map Modal)\"]\n        VIEW3[\"View 3: Network &amp; Disks<br/>(Expanded Throughput Charts &amp; Socket Matrix)\"]\n    end\n\n    CPU_TICKS --> T1\n    MEM_COUNTERS --> T1\n    NET_IO --> T2\n    DISK_IO --> T2\n    SOCKETS --> T2\n    PROCS --> T3\n\n    T1 -->|\"Zero-Alloc O(1) Push\"| RB_CPU_AVG\n    T1 -->|\"Zero-Alloc O(1) Push\"| RB_CORES\n    T1 -->|\"Zero-Alloc O(1) Push\"| RB_MEM\n    T2 -->|\"Zero-Alloc O(1) Push\"| RB_NET\n    T2 -->|\"Zero-Alloc O(1) Push\"| RB_DISK\n\n    RB_CPU_AVG -.->|\"Array View Snapshot\"| SNAP\n    RB_CORES -.->|\"Array View Snapshot\"| SNAP\n    RB_MEM -.->|\"Array View Snapshot\"| SNAP\n    RB_NET -.->|\"Array View Snapshot\"| SNAP\n    RB_DISK -.->|\"Array View Snapshot\"| SNAP\n    T3 -.->|\"Immutable Process List\"| SNAP\n\n    SNAP --> VIEW1\n    SNAP --> VIEW2\n    SNAP --> VIEW3\n                    </div>\n                </div>\n\n                <h2>Core Engineering Subsystems</h2>\n\n                <h3>1. Zero-Allocation Typed Circular Ring Buffer (`RingBuffer.ts`)</h3>\n                <p>\n                    Standard JavaScript arrays (<code>array.push()</code> and <code>array.shift()</code>) are catastrophic for high-frequency telemetry. Every <code>shift()</code> is an $O(N)$ memory copy operation that re-indexes the array and releases old elements to the V8 garbage collector.\n                </p>\n                <p>\n                    Chronos solves this by allocating a fixed-size <strong><code>Float64Array</code></strong> once at startup. A rolling head pointer writes incoming points in $O(1)$ time with modular arithmetic, updating running statistics (minimum, maximum, and rolling sum) without ever reallocating memory:\n                </p>\n\n                <pre><code>export class RingBuffer {\n  private readonly buffer: Float64Array;\n  private head: number = 0;\n  private isFull: boolean = false;\n  private min: number = Infinity;\n  private max: number = -Infinity;\n  private sum: number = 0;\n\n  constructor(public readonly capacity: number) {\n    this.buffer = new Float64Array(capacity);\n  }\n\n  push(value: number): void {\n    if (this.isFull) {\n      const evicted = this.buffer[this.head];\n      this.sum -= evicted;\n      // Recompute min/max only when the evicted item was an extremum\n      if (evicted === this.min || evicted === this.max) {\n        this.recomputeExtrema();\n      }\n    }\n\n    this.buffer[this.head] = value;\n    this.sum += value;\n    if (value &lt; this.min) this.min = value;\n    if (value &gt; this.max) this.max = value;\n\n    this.head = (this.head + 1) % this.capacity;\n    if (this.head === 0) this.isFull = true;\n  }\n\n  // Returns chronological data slice in O(N) without array shifting\n  toArray(): number[] {\n    const size = this.size;\n    const result = new Array&lt;number&gt;(size);\n    const start = this.isFull ? this.head : 0;\n    for (let i = 0; i &lt; size; i++) {\n      result[i] = this.buffer[(start + i) % this.capacity];\n    }\n    return result;\n  }\n}</code></pre>\n\n                <h3>2. Multi-Tier Sampling &amp; Windows Netstat Deltas (`Sampler.ts`)</h3>\n                <p>\n                    Different system counters require vastly different sampling cadences:\n                </p>\n                <ul>\n                    <li><strong>Tier 1 (50ms High-Frequency Fast Loop):</strong> Samples per-core CPU time tick deltas (user, nice, sys, idle, irq) using native <code>os.cpus()</code>. Computing instantaneous delta tick ratios over 50ms intervals yields immediate responsiveness to sudden thread bursts.</li>\n                    <li><strong>Tier 2 (250ms I/O &amp; Socket Loop):</strong> Measures disk read/write throughput and TCP connection tables. On Windows, where network adapter names often contain spaces that lead to null values in higher-level telemetry packages, Chronos executes a fast async fallback parser over <code>netstat -e</code> to compute live Rx/Tx bytes per second.</li>\n                    <li><strong>Tier 3 (1000ms Process Inspection):</strong> Samples top processes sorted by CPU and memory consumption. Scanning the process tree is expensive, so running it every 1000ms prevents telemetry overhead while keeping responsiveness snappy.</li>\n                </ul>\n\n                <h2>Tour of the Chronos Views</h2>\n\n                <h3>View 1: The Overview Dashboard</h3>\n                <p>\n                    The primary dashboard is engineered to fit standard 80-column terminal windows without line wrapping. The CPU panel displays all 16 cores (C00 through C15) in a clean 2-column layout with 5-character bar gauges, real-time percentage indicators, and Unicode sparklines ( \u2582\u2583\u2584\u2585\u2586\u2587\u2588).\n                </p>\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/chronos_dashboard.png\" alt=\"Chronos Tab 1 Dashboard View showing full 16-core CPU utilization, RAM/Swap metrics, and I/O status\" class=\"article-image\" />\n                </div>\n                <p>\n                    The right panel tracks system memory pressure, displaying Free, Active, and Available RAM alongside an 18-width swap gauge. At the bottom, a full-width blue panel provides immediate visibility into Network throughput, Disk Read/Write rates, and TCP connection distribution across <code>ESTAB</code>, <code>LISTEN</code>, <code>TIME_W</code>, and <code>CLOSE_W</code> states.\n                </p>\n\n                <h3>View 2: Process Inspector &amp; Continuous Rolling Scroller</h3>\n                <p>\n                    Pressing <code>2</code> switches to the live <strong>Process Inspector</strong>. Rather than a static paginated table, Chronos implements a smooth <strong>continuous rolling window scroller</strong>:\n                </p>\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/chronos_tab2.png\" alt=\"Chronos Tab 2 Process Inspector with rolling window, fuzzy search, and memory inspection modal\" class=\"article-image\" />\n                </div>\n                <p>\n                    Key capabilities of the Process Inspector include:\n                </p>\n                <ul>\n                    <li><strong>Vim-Style Navigation:</strong> Move line-by-line with <code>j</code> / <code>k</code> (or <code>\u2193</code> / <code>\u2191</code>), jump half-pages with <code>[</code> / <code>]</code>, and jump to top or bottom with <code>g</code> / <code>G</code>.</li>\n                    <li><strong>Live Interactive Search:</strong> Press <code>/</code> to enter instantaneous substring filtering across PID, process name, and user.</li>\n                    <li><strong>Multi-Field Sorting:</strong> Hotkeys <code>c</code> (CPU %), <code>m</code> (Memory %), <code>p</code> (PID), and <code>n</code> (Name) allow instant metric re-indexing.</li>\n                    <li><strong>Memory Map Inspection (`d`):</strong> Opens a modal revealing precise RSS, VSZ, thread count, and executed command-line paths for any selected PID.</li>\n                    <li><strong>Process Termination (`k` / `x`):</strong> Allows issuing <code>SIGTERM</code> or <code>SIGKILL</code> with an interactive confirmation guard.</li>\n                </ul>\n\n                <h3>View 3: Network Throughput &amp; Disks Analysis</h3>\n                <p>\n                    Pressing <code>3</code> opens the dedicated <strong>Network &amp; Disks</strong> tab. This view expands the historical sparkline buffers for dual-axis incoming (Rx) and outgoing (Tx) network bandwidth, disk I/O throughput, and real-time TCP socket state counters:\n                </p>\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/chronos_tab3.png\" alt=\"Chronos Tab 3 Network &amp; Disks throughput charts and TCP socket state distribution\" class=\"article-image\" />\n                </div>\n\n                <h3>View 4: Help &amp; Keybindings Cheatsheet</h3>\n                <p>\n                    Pressing <code>?</code> toggles the built-in <strong>Help &amp; Navigation</strong> cheatsheet modal. It provides instant reference for all keyboard shortcuts, telemetry sampling frequencies, and color legend semantics:\n                </p>\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/chronos_tab4.png\" alt=\"Chronos Tab 4 Help and Keybindings modal with keyboard shortcut guide\" class=\"article-image\" />\n                </div>\n\n                <h2>Terminal Sympathy: Alternate Screen Buffers &amp; Clean Exits</h2>\n                <p>\n                    A critical flaw in many Node.js terminal applications is leaving corrupted cursor positions, hidden cursor states, or overflowing logs after exiting.\n                </p>\n                <p>\n                    Chronos manages the terminal lifecycle with strict ANSI discipline:\n                </p>\n                <ul>\n                    <li><strong>Alternate Screen Buffer:</strong> Chronos automatically switches to the terminal's private alternate buffer upon startup, ensuring that running dashboard frames never pollute the user's primary terminal scrollback history.</li>\n                    <li><strong>Hardware Cursor Concealment:</strong> Automatically suppresses the terminal cursor during active UI rendering loops, eliminating distracting cursor jitter across cells.</li>\n                    <li><strong>Clean Teardown Sequence:</strong> When the user presses <code>q</code> or sends <code>SIGINT</code>, Chronos hooks directly into Ink's exit lifecycle to flush buffers, restore the primary terminal screen, and unhide the cursor so the shell prompt reappears instantly and cleanly.</li>\n                </ul>\n\n                <h2>Technologies &amp; Architecture Highlights</h2>\n                <div class=\"article-tech-row\">\n                    <span class=\"article-tag\">TypeScript</span>\n                    <span class=\"article-tag\">Ink (React in Terminal)</span>\n                    <span class=\"article-tag\">Node.js</span>\n                    <span class=\"article-tag\">Float64Array Ring Buffers</span>\n                    <span class=\"article-tag\">Multi-Tier Sampler</span>\n                    <span class=\"article-tag\">Windows netstat Deltas</span>\n                    <span class=\"article-tag\">Vim-style Scrolling</span>\n                    <span class=\"article-tag\">ANSI Alternate Buffer</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap;\">\n                    <a href=\"https://github.com/Krishnanand-10/Chronos\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                </footer>",
  "argus": "<p>\n                    <strong>Argus</strong> is a high-performance, deterministic full-text search engine engineered entirely from first principles in <strong>TypeScript</strong>. Designed with strict mechanical sympathy for the V8 runtime and modern JavaScript engines, Argus operates with <strong>zero third-party runtime dependencies</strong>. It features inverted positional indices, custom binary serialization with Delta and Variable-Byte compression, Okapi BM25 ranking, and an AST-based boolean and phrase query evaluator.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/argus_preview.png\" alt=\"Argus Search Engine Interface and Terminal Query Execution\" class=\"article-image\" />\n                </div>\n\n                <h2>The Motivation: Why Build a Search Engine from First Principles?</h2>\n                <p>\n                    Full-text search in modern web applications typically offloads retrieval to heavyweight remote daemons (Elasticsearch, Meilisearch) or pulls in opaque WebAssembly binaries. In many embedded contexts\u2014such as local CLI tools, edge workers, and client-side web apps\u2014these solutions present significant hurdles:\n                </p>\n                <ul>\n                    <li><strong>Operational Overhead & Network Latency:</strong> Remote search services introduce network round-trips, separate infrastructure clusters, and complex provisioning pipelines.</li>\n                    <li><strong>Heavy Footprint:</strong> Native binaries and heavy libraries add megabytes to distribution bundles and complicate cross-platform deployment.</li>\n                    <li><strong>Lack of Determinism & Runtime Sympathy:</strong> High-level wrappers frequently trigger erratic V8 garbage collection pauses, deoptimizing hidden classes and allocating excessive intermediate objects.</li>\n                </ul>\n\n                <h2>Core Engineering Principles</h2>\n                <p>\n                    Argus was built from scratch around five strict architectural tenets:\n                </p>\n                <ul>\n                    <li><strong>Zero Runtime Dependencies:</strong> From Unicode character normalization and Porter stemming to binary bit packing and MinHeap priority queues, every component is authored in-house.</li>\n                    <li><strong>Mechanical Sympathy for V8:</strong> Monomorphic call sites, packed continuous typed arrays (`Uint32Array`), and zero-copy byte views prevent engine deoptimizations and GC churn.</li>\n                    <li><strong>Compact Binary Storage:</strong> Inverted postings lists are compressed using delta encoding (D-gaps) and Variable-Byte (VByte) varints, reducing index sizes by up to 75%.</li>\n                    <li><strong>State-of-the-Art Relevance Ranking:</strong> Employs Okapi BM25 scoring with exact term saturation, document length penalization, and Robertson-Sp\u00e4rck Jones inverse document frequency.</li>\n                    <li><strong>Rich Query Semantics:</strong> A formal lexer and recursive-descent parser build an Abstract Syntax Tree (AST) that evaluates boolean logic (`AND`, `OR`, `NOT`), prefix matching (`distrib*`), and positional phrase validation (`\"distributed consensus\"`).</li>\n                </ul>\n\n                <h2>End-to-End Ingestion & Query Architecture</h2>\n                <p>\n                    Argus separates the document lifecycle into an ingestion pipeline (character filtering, tokenization, stemming, inverted indexing) and an evaluation pipeline (AST parsing, candidate scoring, Top-K heap extraction):\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1rem; background: #09090b;\">\n                    <div class=\"mermaid\" style=\"width: 100%; max-width: 100%; overflow: hidden;\">\nflowchart TD\n    subgraph Ingestion [\"1. Document Ingestion Pipeline\"]\n        direction LR\n        D[\"Documents\"] --> TK[\"Tokenizer & Filter\"] --> ST[\"Porter Stemmer\"]\n    end\n\n    subgraph Storage [\"2. Inverted Index & Binary Disk Storage\"]\n        direction LR\n        Lex[\"Term Lexicon Trie\"] --> Post[\"Positional Postings\"] --> Comp[\"Delta + VByte (.argus)\"]\n    end\n\n    subgraph Retrieval [\"3. Query Parsing & Relevance Ranking\"]\n        direction LR\n        Q[\"User Query\"] --> AST[\"AST Boolean Parser\"] --> BM[\"BM25 Scorer\"] --> TopK[\"Min-Heap Top-K Hits\"]\n    end\n\n    Ingestion --> Storage\n    Storage -. \"Zero-Copy Lookup\" .-> Retrieval\n                    </div>\n                </div>\n\n                <h2>Query Lifecycle & AST Evaluation Plan</h2>\n                <p>\n                    When a search query is submitted, Argus parses the token stream into a hierarchical Abstract Syntax Tree before scheduling postings list intersections:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1rem; background: #09090b;\">\n                    <div class=\"mermaid\" style=\"width: 100%; max-width: 100%; overflow: hidden;\">\nsequenceDiagram\n    autonumber\n    actor U as Client\n    participant P as AST Parser\n    participant E as Evaluator\n    participant I as Index Store\n    participant R as BM25 Heap\n\n    U->>P: search('consensus AND \"fault tolerance\"')\n    P->>E: AST Plan: AND(Term, Phrase)\n    E->>I: Fetch postings & skip lists\n    I-->>E: Postings lists & word offsets\n    Note over E: Intersect doc candidates in O(min(N,M))\n    loop Top candidate docIds\n        E->>R: Score via Okapi BM25\n        R->>R: Maintain Top-K in MinHeap\n    end\n    R-->>U: Ranked hits & highlighted snippets\n                    </div>\n                </div>\n\n                <h2>Technical Deep-Dive: Core Subsystems</h2>\n\n                <h3>1. Inverted Index & Positional Postings</h3>\n                <p>\n                    At the heart of Argus is a positional inverted index. Every unique term maps to a postings list recording document occurrences along with exact word offsets:\n                </p>\n\n                <pre><code>interface Posting {\n  docId: number;          // Monotonically increasing document ID\n  termFrequency: number;  // Occurrences in document\n  positions: number[];    // 0-indexed word offsets for phrase verification\n}</code></pre>\n\n                <p>\n                    To speed up multi-term conjunctions (<code>AND</code> queries), postings lists maintain skip pointers positioned at intervals of $\\lfloor\\sqrt{L}\\rfloor$. This allows the evaluator to skip non-matching document blocks in $O(\\min(N, M))$ time rather than scanning every entry linearly.\n                </p>\n\n                <h3>2. Binary Compression: D-Gaps & Variable-Byte Encoding</h3>\n                <p>\n                    Storing raw 32-bit document IDs for dense collections quickly consumes unnecessary memory. Argus applies two complementary compression techniques:\n                </p>\n                <ul>\n                    <li><strong>Delta Encoding (D-Gaps):</strong> Replaces strictly increasing document IDs with differences between consecutive IDs:\n                    <br><code>[104, 108, 125, 160] \u2794 [104, 4, 17, 35]</code></li>\n                    <li><strong>Variable-Byte (VByte) Varint Packing:</strong> Encodes arbitrary integers into 7 data bits per byte, utilizing the highest bit as a continuation indicator. Values smaller than 128 compress from 4 bytes down to a single byte.</li>\n                </ul>\n\n                <pre><code>// Variable-Byte (VByte) integer encoder\nexport function encodeVByte(value: number): number[] {\n  const bytes: number[] = [];\n  while (value >= 128) {\n    bytes.push((value & 0x7f) | 0x80);\n    value >>>= 7;\n  }\n  bytes.push(value & 0x7f);\n  return bytes;\n}\n\nexport function decodeVByte(bytes: Uint8Array, offset: { ptr: number }): number {\n  let result = 0;\n  let shift = 0;\n  while (true) {\n    const byte = bytes[offset.ptr++];\n    result |= (byte & 0x7f) << shift;\n    if ((byte & 0x80) === 0) break;\n    shift += 7;\n  }\n  return result;\n}</code></pre>\n\n                <h3>3. Relevance Scoring via Okapi BM25</h3>\n                <p>\n                    Argus computes document relevance using the industry-standard Okapi BM25 formula with Robertson-Sp\u00e4rck Jones inverse document frequency:\n                </p>\n\n                <pre><code>IDF(t) = ln((N - n(t) + 0.5) / (n(t) + 0.5) + 1)\n\nScore(D, Q) = \u03a3 [ IDF(t) * (f(t, D) * (k1 + 1)) / (f(t, D) + k1 * (1 - b + b * (|D| / avgdl))) ]</code></pre>\n\n                <p>\n                    Where $k_1 = 1.2$ manages term saturation and $b = 0.75$ controls document length normalization. Rather than allocating arrays to sort all candidate documents, Argus feeds calculated scores into a fixed-capacity binary <strong>MinHeap</strong>, guaranteeing $O(N \\log K)$ runtime and minimal allocations.\n                </p>\n\n                <h2>Interactive CLI & Developer Experience</h2>\n                <p>\n                    Argus is packaged with a responsive terminal interface allowing developers to index files, execute complex queries, inspect corpus statistics, or launch an HTTP daemon:\n                </p>\n\n                <ul>\n                    <li><strong><code>npx argus index --source ./docs --output ./indices/docs.argus</code>:</strong> Ingests JSON, Markdown, or text corpora into a compiled binary index.</li>\n                    <li><strong><code>npx argus search --index ./indices/docs.argus \"query\"</code>:</strong> Executes sub-millisecond AST queries with syntax highlighting and snippet extraction.</li>\n                    <li><strong><code>npx argus stats --index ./indices/docs.argus</code>:</strong> Displays document totals, lexicon term counts, and storage metrics.</li>\n                    <li><strong><code>npx argus serve --index ./indices/docs.argus --port 8080</code>:</strong> Starts a local zero-dependency HTTP search endpoint.</li>\n                </ul>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/argus_terminal.png\" alt=\"Argus Terminal CLI Interface - Indexing and Searching\" class=\"article-image\" />\n                </div>\n\n                <h2>In-Browser Web Application: Live Interactive Search</h2>\n                <p>\n                    In addition to the Node.js CLI, Argus is deployed as an in-browser interactive search engine at <a href=\"https://argus-search.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color: #00d2ff; text-decoration: underline;\">argus-search.vercel.app</a>. It compiles and evaluates user queries in real-time with sub-millisecond latency:\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/argus_web.png\" alt=\"Argus In-Browser Search Interface - Real-time BM25 Query Results\" class=\"article-image\" />\n                </div>\n\n                <h2>Programmatic TypeScript Library API</h2>\n                <p>\n                    Argus can be embedded directly into backend services, desktop utilities, or edge runtimes:\n                </p>\n\n                <pre><code>import { ArgusEngine } from 'argus-search';\n\n// 1. Initialize Engine with scoring parameters\nconst engine = new ArgusEngine({\n  k1: 1.2,\n  b: 0.75,\n  stopWords: true,\n  stemming: true,\n});\n\n// 2. Ingest structured documents\nawait engine.addDocuments([\n  {\n    id: 1,\n    title: \"Distributed Systems Architecture\",\n    body: \"Consensus algorithms such as Paxos and Raft ensure high availability and fault tolerance.\",\n  },\n  {\n    id: 2,\n    title: \"Search Engines from First Principles\",\n    body: \"Inverted indexes, postings lists, and Okapi BM25 ranking provide sub-millisecond retrieval.\",\n  },\n]);\n\n// 3. Serialize compiled binary index to disk\nawait engine.commit('./data/library.argus');\n\n// 4. Query with full boolean and phrase syntax\nconst results = await engine.search('consensus AND \"fault tolerance\"', { limit: 5 });\n\nconsole.log(results);</code></pre>\n\n                <h2>Technologies & Algorithms</h2>\n                <div class=\"article-tech-row\">\n                    <span class=\"article-tag\">TypeScript</span>\n                    <span class=\"article-tag\">Okapi BM25</span>\n                    <span class=\"article-tag\">Inverted Index</span>\n                    <span class=\"article-tag\">Positional Postings</span>\n                    <span class=\"article-tag\">Delta Encoding</span>\n                    <span class=\"article-tag\">VByte Compression</span>\n                    <span class=\"article-tag\">AST Query Parser</span>\n                    <span class=\"article-tag\">Min-Heap Top-K</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap;\">\n                    <a href=\"https://argus-search.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\">\n                        Open Live Demo \u2197\n                    </a>\n                    <a href=\"https://github.com/Krishnanand-10/Argus\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                </footer>",
  "p2pcopy": "<p>\n                    <strong>p2pcopy</strong> is a high-performance, open-source peer-to-peer transfer engine that streams files and clipboard payloads directly between developer terminals and web browsers over <strong>WebRTC DataChannels</strong>. There are <strong>zero cloud storage buckets, no accounts, and no intermediate file uploads</strong>. An ephemeral signaling exchange connects peers via an intuitive 6-digit room code, after which all data streams directly device-to-device with end-to-end <strong>DTLS 1.3 / SCTP</strong> encryption.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/p2pcopy_preview.png\" alt=\"p2pcopy Terminal CLI and Live Web Dashboard Interface\" class=\"article-image\" />\n                </div>\n\n                <h2>The Problem: The Insecurity of Cloud Intermediaries</h2>\n                <p>\n                    Sharing files or terminal snippets between developer machines, headless VPS instances, and mobile devices routinely relies on third-party cloud services\u2014such as WeTransfer, Google Drive, Slack, or temporary S3 buckets. This standard workflow introduces severe limitations:\n                </p>\n                <ul>\n                    <li><strong>Secret Leakage:</strong> Sensitive payloads (SSH keys, environment configs, database snapshots, confidential code) sit unencrypted on remote third-party hard drives.</li>\n                    <li><strong>Context Switching:</strong> Developers must leave the terminal, open a browser, sign in, generate upload links, and copy URLs across channels.</li>\n                    <li><strong>Arbitrary Size & Bandwidth Caps:</strong> Free tiers throttle speeds, impose strict file size limits, or delete assets before colleagues download them.</li>\n                </ul>\n\n                <h2>Core Engineering Principles</h2>\n                <p>\n                    To solve this, <code>p2pcopy</code> was architected around four non-negotiable engineering principles:\n                </p>\n                <ul>\n                    <li><strong>Zero Cloud Storage & Zero Knowledge:</strong> No cloud disks, no databases. The signaling server is an in-memory WebSocket broker that exists solely to exchange SDP strings and ICE candidates. Once the DataChannel connects, the room is destroyed immediately from RAM.</li>\n                    <li><strong>Full Terminal \u21c4 Web Interoperability:</strong> Terminal endpoints use native C++ WebRTC bindings (<code>node-datachannel</code>), while browsers leverage standard W3C <code>RTCPeerConnection</code>. Both use identical wire formats (DTLS 1.3 / SCTP).</li>\n                    <li><strong>Constant-Memory Streaming with Backpressure:</strong> Files are read as continuous streams divided into 64KB binary chunks with low-water mark throttling (<code>bufferedAmountLowThreshold</code>). This enables multi-gigabyte transfers with less than 20MB of RAM.</li>\n                    <li><strong>Cryptographic Checksum Verification:</strong> Senders and receivers compute incremental SHA-256 hashes concurrently during transit to guarantee zero corruption or bit rot.</li>\n                </ul>\n\n                <h2>System Topology & WebRTC Architecture</h2>\n                <p>\n                    <code>p2pcopy</code> combines a lightweight, ephemeral signaling relay with direct peer-to-peer WebRTC DataChannels. <strong>Payloads never touch any intermediate server</strong> \u2014 neither the signaling server nor any cloud bucket ever sees your files or clipboard data:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1.5rem; background: #09090b; overflow-x: auto;\">\n                    <div class=\"mermaid\">\nflowchart TD\n    subgraph Relay [\"Ephemeral Signaling Relay (wss://p2pcopy.onrender.com)\"]\n        S1[\"In-Memory Room Code Registry\"]\n        S2[\"SDP Offer / Answer and ICE Candidate Relay\"]\n        S3[\"Zero Storage: Auto-Purged on Connect\"]\n        S1 --- S2 --- S3\n    end\n\n    subgraph Sender [\"Sender (CLI or Browser)\"]\n        A1[\"Input: File Stream or System Clipboard\"]\n        A2[\"Backpressure Flow Controller (64KB Chunks)\"]\n        A3[\"SHA-256 Digest Generator\"]\n        A4[\"WebRTC DataChannel (DTLS 1.3 / SCTP)\"]\n        A1 --> A2 --> A3 --> A4\n    end\n\n    subgraph Receiver [\"Receiver (CLI or Browser)\"]\n        B4[\"WebRTC DataChannel (DTLS 1.3 / SCTP)\"]\n        B3[\"Chunk Assembler and Stream Sink\"]\n        B2[\"SHA-256 Integrity Verifier\"]\n        B1[\"Output: Safe Disk Writer or OS Pasteboard\"]\n        B4 --> B3 --> B2 --> B1\n    end\n\n    A4 -. \"1. Ephemeral SDP and ICE Handshake\" .-> S2\n    S2 -. \"2. Relayed Peer Rendezvous\" .-> B4\n    A4 == \"3. Direct P2P Stream (Zero-Cloud, DTLS 1.3 E2EE)\" ==> B4\n                    </div>\n                </div>\n\n                <h2>Protocol Handshake & Sequence Flow</h2>\n                <p>\n                    Below is the live protocol flow executed during a <code>p2pcopy</code> transfer session:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1.5rem; background: #09090b; overflow-x: auto;\">\n                    <div class=\"mermaid\">\nsequenceDiagram\n    autonumber\n    actor A as Sender (CLI / Browser)\n    participant S as Ephemeral Signaling Relay<br/>(wss://p2pcopy.onrender.com)\n    actor B as Receiver (CLI / Browser)\n\n    Note over A,S: 1. Ephemeral Room Creation\n    A->>S: create_room(\"842-194\")\n    S-->>A: room_created\n    Note over A: Generates SDP Offer and gathers ICE candidates\n\n    Note over B,S: 2. Peer Rendezvous\n    B->>S: join_room(\"842-194\")\n    S-->>B: room_joined\n    S-->>A: peer_joined\n\n    Note over A,B: 3. Ephemeral SDP & ICE Exchange\n    A->>S: send_signal(SDP Offer + ICE)\n    S->>B: relay_signal(SDP Offer + ICE)\n    Note over B: Sets Remote SDP Offer and creates SDP Answer\n    B->>S: send_signal(SDP Answer + ICE)\n    S->>A: relay_signal(SDP Answer + ICE)\n\n    Note over A,B: 4. Direct E2EE WebRTC DataChannel (DTLS 1.3 / SCTP)\n    A--x S: Disconnect signaling WebSocket\n    B--x S: Disconnect signaling WebSocket\n    Note over S: Room \"842-194\" auto-purged from memory\n\n    Note over A,B: 5. Direct Zero-Cloud Stream\n    A->>B: Metadata Handshake (fileName, fileSize, mimeType, isClip)\n    loop 64KB Chunk Streaming with Backpressure\n        A->>B: Binary Chunk (64KB payload)\n        Note over A: Throttled via bufferedAmountLowThreshold\n        Note over B: Streams chunks into disk/RAM + computes SHA-256\n    end\n    A->>B: Transfer Complete (SHA-256 Checksum)\n    Note over B: Validates checksum & saves to disk or OS pasteboard\n                    </div>\n                </div>\n\n                <h2>4 Cross-Platform Transfer Combinations</h2>\n                <p>\n                    Because <code>p2pcopy</code> provides both a lightweight CLI and a zero-install browser interface, it supports all four communication vectors:\n                </p>\n\n                <div class=\"table-wrapper\" style=\"overflow-x: auto; margin: 1rem 0; border: 1px solid var(--border); border-radius: 10px; background: #09090b;\">\n                    <table style=\"width: 100%; border-collapse: collapse; font-size: 0.9rem; text-align: left;\">\n                        <thead>\n                            <tr style=\"border-bottom: 1px solid var(--border); background: rgba(255, 255, 255, 0.03);\">\n                                <th style=\"padding: 12px 16px; color: #ffffff;\">Combination</th>\n                                <th style=\"padding: 12px 16px; color: #ffffff;\">Flow</th>\n                                <th style=\"padding: 12px 16px; color: #ffffff;\">Real-World Use Case</th>\n                            </tr>\n                        </thead>\n                        <tbody>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #00d2ff;\">Terminal \u2794 Terminal</td>\n                                <td style=\"padding: 12px 16px;\"><code>p2pcopy send &lt;file&gt;</code> \u2794 <code>p2pcopy receive &lt;code&gt;</code></td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Machine-to-machine streaming between developer terminals.</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #34d399;\">Terminal \u2794 Browser</td>\n                                <td style=\"padding: 12px 16px;\"><code>p2pcopy send &lt;file&gt;</code> \u2794 Web tab</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Beam archives from a headless cloud server directly to a phone or laptop browser.</td>\n                            </tr>\n                            <tr style=\"border-bottom: 1px solid var(--border-subtle);\">\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #a855f7;\">Browser \u2794 Terminal</td>\n                                <td style=\"padding: 12px 16px;\">Web tab \u2794 <code>p2pcopy receive &lt;code&gt;</code></td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">Teammate drops a file in their browser; you receive it directly into your terminal folder.</td>\n                            </tr>\n                            <tr>\n                                <td style=\"padding: 12px 16px; font-weight: 600; color: #f59e0b;\">Browser \u2794 Browser</td>\n                                <td style=\"padding: 12px 16px;\">Web tab \u2794 Web tab</td>\n                                <td style=\"padding: 12px 16px; color: #a1a1aa;\">100% zero-install, direct peer-to-peer web transfers between any two devices.</td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n\n                <h2>Chunked Streaming with Backpressure Flow Control</h2>\n                <p>\n                    WebRTC DataChannels operate over SCTP. Without flow control, blasting gigabytes of data into a socket will rapidly overflow kernel memory or trigger unrecoverable packet drops. <code>p2pcopy</code> implements precise backpressure throttling using <code>bufferedAmountLowThreshold</code>:\n                </p>\n\n                <pre><code>// Chunked SCTP streaming with bufferedAmountLow backpressure flow control\nconst streamFileOverDataChannel = async (channel: RTCDataChannel, fileStream: fs.ReadStream) => {\n  const CHUNK_SIZE = 64 * 1024; // 64KB SCTP chunks\n  channel.bufferedAmountLowThreshold = 256 * 1024; // 256KB low-water mark\n\n  for await (const chunk of fileStream) {\n    if (channel.bufferedAmount > 1024 * 1024) { // Pause read when buffer reaches 1MB\n      await new Promise((resolve) => { \n        channel.onbufferedamountlow = () => {\n          channel.onbufferedamountlow = null;\n          resolve(true);\n        };\n      });\n    }\n    channel.send(chunk);\n  }\n};</code></pre>\n\n                <h2>Six Commands, Zero Config</h2>\n                <p>\n                    <code>p2pcopy</code> provides six streamlined CLI commands designed for maximum developer ergonomics:\n                </p>\n                <ul>\n                    <li><strong><code>p2pcopy send &lt;file&gt;</code>:</strong> Stream files or archives directly with real-time transfer progress and SHA-256 verification.</li>\n                    <li><strong><code>p2pcopy receive &lt;code&gt;</code>:</strong> Enter the 6-digit pairing code to download incoming files directly into your current directory.</li>\n                    <li><strong><code>p2pcopy clip</code>:</strong> Beam your system pasteboard or pipe command output (<code>cat id_rsa.pub | p2pcopy clip</code>).</li>\n                    <li><strong><code>p2pcopy clip get &lt;code&gt;</code>:</strong> Write directly to system pasteboard or stream to stdout for pipelines (<code>p2pcopy clip get 842-194 --no-copy | jq .</code>).</li>\n                    <li><strong><code>p2pcopy signal --port 9000</code>:</strong> Self-host a zero-storage WebSocket signaling relay on a private or air-gapped network.</li>\n                    <li><strong><code>--ice &lt;urls...&gt;</code>:</strong> Traverse strict corporate symmetric NATs, cellular CGNATs, or firewalls with custom STUN/TURN relays.</li>\n                </ul>\n\n                <h2>Sender Experience: 6-Digit Ephemeral Pairing</h2>\n                <p>\n                    Whether initiated from a developer terminal with <code>npx p2pcopy send &lt;file&gt;</code> or dragged into the browser interface at <a href=\"https://p2pcopy.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color: #00d2ff; text-decoration: underline;\">p2pcopy.vercel.app</a>, the sender registers an ephemeral room and displays a 6-digit pairing code. As soon as the receiver joins, chunked streaming begins:\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/p2pcopy_send.png\" alt=\"p2pcopy Sender Interface - Streaming File with 6-Digit Pairing Code\" class=\"article-image\" />\n                </div>\n\n                <h2>Receiver Experience: Instant Download & Verification</h2>\n                <p>\n                    The receiver inputs the 6-digit code or connects via URL. Chunks stream directly into local memory or disk, while an ongoing SHA-256 hash is verified against the sender's integrity digest before final write:\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/p2pcopy_receive.png\" alt=\"p2pcopy Receiver Interface - Direct Web and Terminal Download\" class=\"article-image\" />\n                </div>\n\n                <h2>In-Browser Web Application: Zero-Install Transfers</h2>\n                <p>\n                    For peers on devices without terminal access (such as mobile phones, tablets, or non-technical teammates), the live web app at <a href=\"https://p2pcopy.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" style=\"color: #00d2ff; text-decoration: underline;\">p2pcopy.vercel.app</a> provides direct browser-to-browser and terminal-to-browser transfers:\n                </p>\n                <ul>\n                    <li><strong>Web Sender:</strong> Drag & drop any file or paste clipboard text to immediately generate an ephemeral 6-digit code.</li>\n                    <li><strong>Web Receiver:</strong> Enter the 6-digit pairing code to download streamed files or copy beamed clipboard content directly with 1 click.</li>\n                </ul>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/p2pcopy_web.png\" alt=\"p2pcopy In-Browser Web Transfer Interface - Send File or Beam Clipboard\" class=\"article-image\" />\n                </div>\n\n                <h2>Programmatic Library API</h2>\n                <p>\n                    In addition to the CLI and web app, <code>p2pcopy</code> is distributed as a typed TypeScript library for automated peer-to-peer data pipelines:\n                </p>\n\n                <pre><code>import { WebRTCPeer, SignalingClient, FileSender } from \"p2pcopy\";\n\n// 1. Connect to signaling relay\nconst signal = new SignalingClient(\"wss://p2pcopy.onrender.com\");\nawait signal.connect();\nawait signal.createRoom(\"842-194\");\n\n// 2. Initialize WebRTC peer\nconst peer = new WebRTCPeer({\n  name: \"sender\",\n  isInitiator: true,\n  roomId: \"842-194\",\n  signalingClient: signal,\n});\nawait peer.start();\n\n// 3. Stream file directly device-to-device\npeer.on(\"connected\", async (dataChannel) => {\n  const sender = new FileSender({\n    filePath: \"./dataset.tar.gz\",\n    dataChannel,\n    showProgress: true,\n  });\n  await sender.send();\n});</code></pre>\n\n                <h2>Systems Insight: 3-Tier NAT Traversal</h2>\n                <pre><code>[Tier 1: Direct LAN / UPnP]\n          \u2502 (Zero NAT, Maximum Speed)\n          \u25bc\n[Tier 2: STUN Hole-Punching]\n          \u2502 (Succeeds on ~85-90% of home & office NATs)\n          \u25bc\n[Tier 3: Encrypted TURN Blind Relay]\n            (Guaranteed delivery for Symmetric NATs, CGNAT, & strict enterprise firewalls)</code></pre>\n                <p>\n                    When direct UDP hole-punching fails due to strict enterprise symmetric NATs, <code>p2pcopy</code> automatically falls back to an encrypted TURN relay. Crucially, TURN relays only forward encrypted DTLS frames\u2014no plaintext payload data is ever readable by the relay server.\n                </p>\n\n                <h2>Technologies Used</h2>\n                <div class=\"article-tech-row\">\n                    <span class=\"article-tag\">TypeScript</span>\n                    <span class=\"article-tag\">WebRTC DataChannel</span>\n                    <span class=\"article-tag\">Node.js (node-datachannel)</span>\n                    <span class=\"article-tag\">WebSocket (ws)</span>\n                    <span class=\"article-tag\">DTLS 1.3 / SCTP</span>\n                    <span class=\"article-tag\">Vite & Tailwind CSS</span>\n                    <span class=\"article-tag\">SHA-256 Crypto</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap;\">\n                    <a href=\"https://p2pcopy.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\">\n                        Open Live App \u2197\n                    </a>\n                    <a href=\"https://github.com/Krishnanand-10/p2pcopy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                    <a href=\"https://www.npmjs.com/package/p2pcopy\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        npm Package\n                    </a>\n                </footer>",
  "termux-antigravity": "<p>\n                    <strong>What if you didn\u2019t need a laptop to build Android apps at all?</strong> No bulky workstation, no 12GB Android Studio setup, and no cloud build servers. Just an Android smartphone, a terminal app, a small Linux layer, and an AI coding agent compiling native code right in your hands.\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"max-width: 580px; margin: 1.5rem auto;\">\n                    <img src=\"/images/cleanfiles_preview.png\" alt=\"CleanFiles On-Device Autonomous Android Development with Termux and Antigravity CLI\" class=\"article-image\" />\n                </div>\n\n                <h2>The Spark: Can a Phone Replace a Laptop?</h2>\n                <p>\n                    This experiment started when my friend shared an interesting idea: <em>what if we ran the Antigravity CLI directly on an Android phone using Termux, and turned the phone itself into a complete development environment?</em>\n                </p>\n                <p>\n                    Today\u2019s smartphones are remarkably fast. Modern phone processors are easily as capable as many laptops were just a few years back. Still, almost everyone assumes building an Android app requires a computer with a heavy IDE like Android Studio, gigabytes of build tools, and constant emulator testing.\n                </p>\n                <p>\n                    I was curious to see if that was actually true, or if we just do it out of habit. So I decided to test it myself: install Termux, set up an Ubuntu environment inside it, configure the Antigravity CLI agent, and see if I could write, compile, and run a real native app without touching a computer once.\n                </p>\n\n                <h2>Why I Built CleanFiles: Escaping the Ads</h2>\n                <p>\n                    I didn't want to build just another generic demo app; I wanted to solve an annoying problem I deal with every day. Like a lot of Android users, I was tired of the default file manager that came pre-installed on my phone. A basic utility that should just open folders and show downloaded files had become completely loaded with ads: <strong>full-screen popups, banner ads taking up screen space, random 'app recommendations', and unnecessary permission requests</strong>.\n                </p>\n                <p>\n                    Every time I needed to find a downloaded PDF, move camera photos, or clean up storage, I had to wait through an ad or be careful not to accidentally tap sponsored links.\n                </p>\n                <p>\n                    So the goal became clear: use this mobile setup to build <strong>CleanFiles</strong>\u2014a clean, fast, and completely ad-free file manager with zero bloat and total privacy, built and compiled right on the phone.\n                </p>\n\n                <h2>System Architecture: How It Works on the Phone</h2>\n                <p>\n                    To run both the AI coding agent and the Android build tools on an unrooted phone, we set up a clean three-layer system:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1.5rem; background: #09090b; overflow-x: auto;\">\n                    <div class=\"mermaid\">\nflowchart TD\n    subgraph Host [\"1. Android Host OS\"]\n        TERMUX[\"Termux Terminal App\"]\n        BRIDGE[\"Storage Bridge (/sdcard/Download)\"]\n        INSTALLER[\"Android Package Installer\"]\n    end\n\n    subgraph PRoot [\"2. Linux Environment (PRoot)\"]\n        UBUNTU[\"Ubuntu 24.04 LTS (ARM64)\"]\n        AGENT[\"Antigravity CLI Agent\"]\n        SDK[\"Android CLI Build Tools (aapt, d8, zipalign, apksigner)\"]\n    end\n\n    subgraph Pipeline [\"3. On-Device Build Pipeline\"]\n        PROMPT[\"User Prompt: 'Build CleanFiles Utility'\"]\n        SRC[\"Java Sources + AndroidManifest.xml\"]\n        R_JAVA[\"Resource Compilation &amp; R.java (aapt)\"]\n        BYTECODE[\"Java Bytecode (javac)\"]\n        DEX[\"Dalvik Executable (classes.dex via D8)\"]\n        UNALIGNED[\"Unaligned Package (aapt)\"]\n        ALIGNED[\"Memory Alignment (zipalign)\"]\n        SIGNED_APK[\"Signed CleanFiles.apk (42 KB)\"]\n    end\n\n    TERMUX --> UBUNTU\n    UBUNTU --> AGENT\n    PROMPT --> AGENT\n    AGENT --> SRC\n    SRC --> R_JAVA\n    R_JAVA --> BYTECODE\n    BYTECODE --> DEX\n    DEX --> UNALIGNED\n    UNALIGNED --> ALIGNED\n    ALIGNED --> SIGNED_APK\n    SIGNED_APK --> BRIDGE\n    BRIDGE --> INSTALLER\n                    </div>\n                </div>\n\n                <h2>The Workflow</h2>\n                <div class=\"article-tech-row\" style=\"margin: 1rem 0 1.5rem;\">\n                    <span class=\"article-tag\" style=\"font-size: 0.95rem; font-weight: 600;\">\n                        Android &rarr; Termux &rarr; Ubuntu 24.04 &rarr; Antigravity CLI &rarr; Native Project &rarr; APK\n                    </span>\n                </div>\n                <p>\n                    No laptop. No USB debugging cables. No remote servers. The phone itself wrote the code, packaged the resources, compiled the Java classes into Dalvik bytecode, signed the package, and installed the finished app right onto its own operating system.\n                </p>\n\n                <h2>Phase 1: Setting Up the Mobile Linux Environment</h2>\n                <p>\n                    Standard Android development uses Gradle, which downloads gigabytes of dependencies and easily overwhelms a mobile phone's memory. Instead, we used a lightweight, <strong>headless command-line toolchain</strong> inside Ubuntu 24.04 via PRoot:\n                </p>\n                <ul>\n                    <li><strong>Termux &amp; PRoot:</strong> Termux gives us a standard terminal, while <code>proot-distro</code> installs a clean Ubuntu 24.04 LTS Linux system with standard library support.</li>\n                    <li><strong>Java Compiler:</strong> <code>openjdk-17-jdk-headless</code> for fast Java compiling without any graphical bloat.</li>\n                    <li><strong>Android Build Tools:</strong> Standalone ARM64 command-line tools: <code>aapt</code> (packaging), <code>d8</code> (dex compiler), <code>zipalign</code>, and <code>apksigner</code> alongside <code>android.jar</code> (API 33).</li>\n                    <li><strong>Storage Access:</strong> Running <code>termux-setup-storage</code> gives the terminal permission to read and write directly to the phone's internal storage (like the <code>/sdcard/Download</code> folder).</li>\n                </ul>\n\n                <h2>Phase 2: Designing CleanFiles with the AI Agent</h2>\n                <p>\n                    I gave the prompt to Antigravity CLI straight from the phone's terminal. We worked through the project layout together, and let the agent create the files.\n                </p>\n                <p>\n                    We designed CleanFiles with the essential features a good file manager needs:\n                </p>\n                <ul>\n                    <li><strong>Live Storage Overview:</strong> Checking storage space in real time down to the byte, with a visual progress bar (like <em>56.3 GB used out of 64 GB, 87%</em>).</li>\n                    <li><strong>Quick Category Breakdown:</strong> Fast scanning across the device to calculate how much space is taken up by <strong>Photos</strong>, <strong>Videos</strong>, and <strong>Audio</strong>.</li>\n                    <li><strong>Folder Navigator:</strong> Easy tabbed browsing between <em>Internal Storage</em>, <em>Downloads</em>, and <em>Recent Files</em> with item counts and clear folder icons.</li>\n                    <li><strong>Zero Ads &amp; Complete Privacy:</strong> Built using only standard Android SDK components\u2014no tracking scripts, no third-party ad networks, and instant launch times.</li>\n                </ul>\n\n                <h2>Phase 3: The 5-Step Headless Compilation Sequence</h2>\n                <p>\n                    Antigravity CLI organized the build steps, checked the manifest, and ran the whole compilation sequence right in the terminal. Here is the actual terminal screenshot showing the agent running each command:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"max-width: 310px; margin: 2rem auto; border-radius: 20px; border: 1px solid rgba(255,255,255,0.18); box-shadow: 0 12px 32px rgba(0,0,0,0.6); overflow: hidden;\">\n                    <img src=\"/images/cleanfiles_termux_cli.jpg\" alt=\"Antigravity CLI Compiling CleanFiles inside Termux on Android\" class=\"article-image\" style=\"width: 100%; display: block;\" />\n                </div>\n                <p style=\"text-align: center; font-size: 0.85rem; color: var(--secondary); margin-top: -1rem; margin-bottom: 2rem;\">1. Live Termux session: Antigravity CLI compiling bytecode, dexing, and signing the APK</p>\n\n                <h3>Step 1: Resource Packaging (<code>aapt</code>)</h3>\n                <p>\n                    Compiling app icons, layouts, and values into the resource table and generating the <code>R.java</code> file:\n                </p>\n                <pre><code># Compile resources and generate R.java\naapt package -f -m     -J /root/CleanFiles/src     -M /root/CleanFiles/AndroidManifest.xml     -S /root/CleanFiles/res     -I /opt/android-sdk/platforms/android-33/android.jar</code></pre>\n\n                <h3>Step 2: Java Compilation (<code>javac</code>)</h3>\n                <p>\n                    Compiling all Java source files (activities, storage scanners, and <code>R.java</code>) into standard Java bytecode:\n                </p>\n                <pre><code>mkdir -p /root/CleanFiles/build/classes\njavac -d /root/CleanFiles/build/classes     -cp /opt/android-sdk/platforms/android-33/android.jar     $(find /root/CleanFiles/src -name \"*.java\")</code></pre>\n\n                <h3>Step 3: Creating Dalvik Bytecode (<code>d8</code>)</h3>\n                <p>\n                    Converting the Java <code>.class</code> files into Android's native Dalvik executable format (<code>classes.dex</code>):\n                </p>\n                <pre><code>mkdir -p /root/CleanFiles/build/dex\nd8 /root/CleanFiles/build/classes/com/cleanfiles/app/*.class     --lib /opt/android-sdk/platforms/android-33/android.jar     --output /root/CleanFiles/build/dex</code></pre>\n\n                <h3>Step 4: Packaging and Memory Alignment (<code>aapt</code> &amp; <code>zipalign</code>)</h3>\n                <p>\n                    Packing the <code>classes.dex</code> file and resources into an APK, then aligning it on 4-byte boundaries so the Android OS can load it quickly:\n                </p>\n                <pre><code># Package initial unaligned APK\naapt package -f     -M /root/CleanFiles/AndroidManifest.xml     -S /root/CleanFiles/res     -I /opt/android-sdk/platforms/android-33/android.jar     -F /root/CleanFiles/build/cleanfiles-unaligned.apk     /root/CleanFiles/build/dex\n\n# Align on 4-byte boundaries for fast loading\nzipalign -p -f 4     /root/CleanFiles/build/cleanfiles-unaligned.apk     /root/CleanFiles/build/CleanFiles.apk</code></pre>\n\n                <h3>Step 5: Signing the APK (<code>apksigner</code>)</h3>\n                <p>\n                    Signing the final APK with an on-device security key using modern Android signing schemes (v1, v2, and v3):\n                </p>\n                <pre><code>apksigner sign --ks /root/release.keystore     --ks-key-alias release     --ks-pass pass:android     /root/CleanFiles/build/CleanFiles.apk</code></pre>\n\n                <p>\n                    The result? A super-lightweight, native Android app measuring just <strong>42 KB</strong>\u2014smaller than almost any image on a modern website!\n                </p>\n\n                <h2>Phase 4: Installing and Running the App on Device</h2>\n                <p>\n                    One of the coolest parts of the whole experiment was installing the app. Usually with a laptop, you connect a USB cable, turn on USB debugging, and run <code>adb install</code>.\n                </p>\n                <p>\n                    In our setup, the agent simply copied the signed APK to the phone's Download folder and called a Termux command to trigger Android's native installer:\n                </p>\n                <pre><code># Copy signed APK to the phone's Download directory\ncp /root/CleanFiles/build/CleanFiles.apk /sdcard/Download/CleanFiles.apk\n\n# Tell Android to open and install the APK\ntermux-open /sdcard/Download/CleanFiles.apk</code></pre>\n\n                <p>\n                    Right away, the phone's standard <em>\"Do you want to install this app?\"</em> dialog popped up on screen. With one tap, <strong>CleanFiles was installed and running live on the very phone that wrote and compiled it</strong>.\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"max-width: 310px; margin: 2rem auto; border-radius: 20px; border: 1px solid rgba(255,255,255,0.18); box-shadow: 0 12px 32px rgba(0,0,0,0.6); overflow: hidden;\">\n                    <img src=\"/images/cleanfiles_app_ui.jpg\" alt=\"CleanFiles Native Android App Running on Device\" class=\"article-image\" style=\"width: 100%; display: block;\" />\n                </div>\n                <p style=\"text-align: center; font-size: 0.85rem; color: var(--secondary); margin-top: -1rem; margin-bottom: 2rem;\">2. CleanFiles running live on device: clean dark theme, zero ads, instant storage telemetry</p>\n\n                <h2>The Realities: What Worked and What Was Difficult</h2>\n                <p>\n                    While the experiment worked surprisingly well, developing on a phone isn't about to replace a dual-monitor desktop setup just yet. A few practical realities came up:\n                </p>\n                <ul>\n                    <li><strong>Typing on a Touchscreen:</strong> Entering commands, editing long paths, and selecting text with a virtual keyboard gets tiring quickly. If you want to do serious work this way, a small Bluetooth keyboard makes a huge difference.</li>\n                    <li><strong>Setting Up the Tools:</strong> Getting the Android command-line tools to play nicely inside an Ubuntu PRoot layer on Android takes some initial setup and patience with system paths.</li>\n                    <li><strong>Battery and Heat:</strong> Running an AI agent, compiling Java code, and packaging the APK puts real load on the phone's processor. It warms up the device and drains the battery faster than normal usage.</li>\n                    <li><strong>Checking the Code:</strong> Even with an agent helping you, you still need to review the code, catch layout mistakes, and verify that Android permissions are configured properly.</li>\n                </ul>\n\n                <h2>Key Takeaways: Building Software Anywhere</h2>\n                <p>\n                    Despite the small challenges, the takeaway from this project is genuinely exciting:\n                </p>\n                <ol>\n                    <li><strong>The Barrier to Building Has Dropped:</strong> You don't need a high-end computer or gigabytes of desktop software to create working native apps. A regular smartphone in your pocket can brainstorm, write code, compile it, and run the finished product.</li>\n                    <li><strong>AI Agents Can Work in Minimal Environments:</strong> Autonomous coding agents aren't limited to desktop code editors. When given access to a terminal, they can run compilers, fix build errors, and complete full development cycles independently.</li>\n                    <li><strong>True Computing Freedom:</strong> Whether you want to fix a bug on a train or build a quick tool while away from your desk, your phone is fully capable of being an actual creation tool.</li>\n                </ol>",
  "repurpose-ai": "<p>\n                    <strong>RepurposeAI</strong> is an AI-powered SaaS platform that allows creators, founders, and marketers to paste a <strong>YouTube video URL</strong>, <strong>blog post link</strong>, or <strong>raw transcript</strong> and transform it into a full multi-platform distribution asset bundle in seconds.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/repurpose_ai_preview.png\" alt=\"RepurposeAI SaaS Landing Page\" class=\"article-image\" />\n                </div>\n\n                <h2>What it is</h2>\n                <p>\n                    RepurposeAI eliminates the manual grind of cross-platform distribution. Instead of spending hours rewriting content for each social network, users input a single source piece and instantly receive customized, platform-tailored formats including LinkedIn carousel summaries, Twitter/X narrative threads, short-form video scripts (for Reels/TikTok/Shorts), SEO meta tags, and newsletter digests.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/repurpose_ai_dashboard.png\" alt=\"RepurposeAI Repurposing Studio Dashboard\" class=\"article-image\" />\n                </div>\n\n                <h2>How it is built</h2>\n                <p>\n                    Built with <strong>Next.js 15</strong> App Router, <strong>TypeScript</strong>, and <strong>Tailwind CSS</strong>. It connects to <strong>Google Gemini Flash</strong> for lightning-fast structured JSON generation. The backend implements YouTube transcript scraping, HTML article extraction via Cheerio, database modeling with <strong>Prisma ORM</strong>, and metered subscription billing powered by <strong>Stripe</strong>.\n                </p>\n                \n                <h2>System Architecture</h2>\n                <p>\n                    RepurposeAI is engineered with an asynchronous content extraction pipeline, structured LLM schema parsing, and a metered billing engine backed by Stripe webhooks and Prisma ORM persistence:\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/repurpose_ai_architecture.png\" alt=\"RepurposeAI System Architecture Diagram\" class=\"article-image\" />\n                </div>\n\n                <pre><code>const generateAssetBundle = async (rawTranscript: string) => {\n  const model = genAI.getGenerativeModel({ model: \"gemini-1.5-flash\" });\n  const response = await model.generateContent({\n    contents: [{ role: \"user\", parts: [{ text: buildRepurposePrompt(rawTranscript) }] }],\n    generationConfig: { responseMimeType: \"application/json\" }\n  });\n  return JSON.parse(response.text());\n};</code></pre>\n\n                <h2>Core Features</h2>\n                <ul>\n                    <li>\ud83c\udfa5 <strong>Multi-Source Ingestion:</strong> Ingest YouTube video links, web article URLs, or raw text directly.</li>\n                    <li>\ud83d\udcbc <strong>LinkedIn Carousels:</strong> Formatted hooks, structured bullet points, and CTAs ready to publish.</li>\n                    <li>\ud83d\udc26 <strong>Twitter/X Threads:</strong> 5\u20138 tweet narrative flows with 1-click individual copy controls.</li>\n                    <li>\ud83c\udfac <strong>Short-Form Video Scripts:</strong> Ready-to-record Reels, Shorts, and TikTok scripts with scene-by-scene visual cues and voiceovers.</li>\n                    <li>\ud83d\udd0d <strong>SEO Meta Pack:</strong> Optimized titles, 160-character descriptions, keywords, and Google SERP previews.</li>\n                    <li>\ud83d\udcb3 <strong>Stripe Metered Billing:</strong> Built-in credit management and subscription webhooks.</li>\n                </ul>\n\n                <h2>Technologies Used</h2>\n                <div class=\"article-tech-row\">\n                    <span class=\"article-tag\">Next.js 15</span>\n                    <span class=\"article-tag\">TypeScript</span>\n                    <span class=\"article-tag\">Google Gemini</span>\n                    <span class=\"article-tag\">Prisma ORM</span>\n                    <span class=\"article-tag\">Stripe</span>\n                    <span class=\"article-tag\">Tailwind CSS</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap;\">\n                    <a href=\"https://repurposeai-rp.vercel.app/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\">\n                        Open Live App \u2197\n                    </a>\n                    <a href=\"https://github.com/Krishnanand-10/RepurposeAI\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                </footer>",
  "kinship": "<p>\n                    <strong>Kinship</strong> is a modern, full-stack lineage visualization platform engineered around an interactive infinite panning and zooming canvas. It eliminates the clunky, tangled trees typical of legacy genealogy software by introducing <strong>automated symmetric marriage junctions, collision-free sibling row alignment, persistent spatial coordinate memory</strong>, and granular collaborator permissions powered by <strong>Supabase</strong>.\n                </p>\n\n                <h2>The Problem: The Geometric Complexity of Genealogy Graphs</h2>\n                <p>\n                    Family trees are deceptive. While superficially resembling standard hierarchical trees (like organizational charts or file systems), <strong>genealogical graphs are Directed Acyclic Graphs (DAGs) with bidirectional lateral constraints</strong>:\n                </p>\n                <ul>\n                    <li><strong>Spouse Pairing Dilemma:</strong> Two unrelated nodes (spouses) must sit on the exact same vertical tier, joined horizontally, without pushing other branches out of scope.</li>\n                    <li><strong>Line-Crossing Chaos:</strong> Children belong equally to two parents. In naive force-directed layouts, connection lines cross directly over other family members, quickly becoming an unreadable \"spaghetti graph.\"</li>\n                    <li><strong>Loss of Spatial Mental Models:</strong> Most web visualizers recalculate node coordinates on every browser refresh. Users lose their visual bearings because grandparents and cousins jump to completely arbitrary screen positions.</li>\n                </ul>\n\n                <h2>System Architecture &amp; Data Flow</h2>\n                <p>\n                    Kinship decouples the infinite vector canvas rendering from coordinate calculation math and cloud database persistence:\n                </p>\n\n                <div class=\"article-image-wrapper\" style=\"padding: 1.5rem; background: #09090b; overflow-x: auto;\">\n                    <div class=\"mermaid\">\nflowchart TD\n    subgraph Canvas [\"1. Interactive Infinite Canvas (React Flow + Vite)\"]\n        N1[\"Person Nodes (Photos, Vital Metadata, Gender)\"]\n        J1[\"Symmetric Marriage Junction Nodes\"]\n        R1[\"Orthogonal Comb & L-Edge Routing Engine\"]\n        N1 --- J1\n        J1 --- R1\n    end\n\n    subgraph Algorithms [\"2. Coordinate & Layout Engine\"]\n        A1[\"Spouse Midpoint Calculus: (x1+x2)/2, (y1+y2)/2\"]\n        A2[\"Sibling Row Alignment & Horizontal Spacing\"]\n        A3[\"Viewport Transform Memory & Collision Avoidance\"]\n        A1 --> A3\n        A2 --> A3\n    end\n\n    subgraph Backend [\"3. Relational Storage & BaaS (Supabase)\"]\n        AUTH[\"Supabase Auth (OAuth + Sessions)\"]\n        DB_P[\"people (Coordinates & Vital Dates)\"]\n        DB_R[\"relationships (Parent, Spouse, Sibling)\"]\n        DB_S[\"branch_shares (RBAC: Viewer / Editor)\"]\n        AUTH --- DB_P\n        DB_P --- DB_R\n        DB_R --- DB_S\n    end\n\n    subgraph Export [\"4. Document & Raster Export\"]\n        H2C[\"html2canvas Viewport Rasterizer\"]\n        PDF[\"jspdf Vector Document Compiler\"]\n        H2C --> PDF\n    end\n\n    J1 <--> A1\n    R1 <--> A3\n    N1 <--> DB_P\n    J1 <--> DB_R\n    Canvas --> H2C\n                    </div>\n                </div>\n\n                <h2>1. Symmetric Marriage Junction Algorithm</h2>\n                <p>\n                    In Kinship, spouses are not linked with messy intersecting bezier curves. Instead, a dedicated, invisible-yet-snappable <strong>Marriage Junction Node</strong> is dynamically injected into the graph between married partners:\n                </p>\n                <p>\n                    The junction node calculates its position precisely halfway between both partners along the X axis, positioned slightly below their node baseline:\n                </p>\n\n                <pre><code>// Dynamic marriage junction coordinate calculator\nexport function calculateMarriageJunction(partnerA, partnerB, verticalGutter = 48) {\n  const midX = (partnerA.position.x + partnerB.position.x) / 2;\n  const midY = Math.max(partnerA.position.y, partnerB.position.y) + verticalGutter;\n\n  return {\n    id: `junction-${partnerA.id}-${partnerB.id}`,\n    type: 'marriageJunction',\n    position: { x: midX, y: midY },\n    data: { spouses: [partnerA.id, partnerB.id] },\n    selectable: false,\n    draggable: false,\n  };\n}</code></pre>\n\n                <p>\n                    All shared children then connect directly to this single junction node via <strong>\"Comb\" orthogonal edge routing</strong>. This guarantees zero edge intersections between spouses and eliminates visual clutter.\n                </p>\n\n                <div class=\"article-image-wrapper\">\n                    <img src=\"/images/kinship_preview.png\" alt=\"Kinship Interactive Infinite Canvas with Marriage Junctions and Member Cards\" class=\"article-image\" />\n                </div>\n\n                <h2>2. Sibling Row Alignment &amp; Collision Avoidance</h2>\n                <p>\n                    When a couple has multiple children, placing them manually can be tedious. Kinship incorporates an automated sibling alignment pass:\n                </p>\n                <ul>\n                    <li><strong>Subtree Bounding Box Calculation:</strong> Determines the cumulative width of each child's own downstream descendants.</li>\n                    <li><strong>Single-Row Equal Distribution:</strong> Arranges all direct siblings on a uniform horizontal plane with predictable padding (e.g., 220px gutter between cards).</li>\n                    <li><strong>Lineage Centering:</strong> Centers the sibling row directly beneath the parental marriage junction, ensuring clean bilateral symmetry.</li>\n                </ul>\n\n                <h2>3. Spatial Persistence &amp; Database Architecture</h2>\n                <p>\n                    Unlike temporary chart viewers, Kinship preserves exact user layout customizations. Every person in the family tree stores their <code>x</code> and <code>y</code> canvas coordinates directly in Supabase PostgreSQL:\n                </p>\n\n                <pre><code>-- Kinship Database Schema (Supabase PostgreSQL)\nCREATE TABLE public.people (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    full_name TEXT NOT NULL,\n    birth_date DATE,\n    death_date DATE,\n    gender TEXT CHECK (gender IN ('male', 'female', 'other')),\n    photo_url TEXT,\n    notes TEXT,\n    x FLOAT DEFAULT NULL, -- Spatial Canvas Coordinates\n    y FLOAT DEFAULT NULL,\n    branch_id UUID REFERENCES public.family_branches(id) ON DELETE CASCADE,\n    created_at TIMESTAMPTZ DEFAULT now()\n);\n\nCREATE TABLE public.relationships (\n    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n    person_a UUID REFERENCES public.people(id) ON DELETE CASCADE,\n    person_b UUID REFERENCES public.people(id) ON DELETE CASCADE,\n    type TEXT DEFAULT 'parent' CHECK (type IN ('parent', 'spouse', 'sibling')),\n    created_at TIMESTAMPTZ DEFAULT now()\n);</code></pre>\n\n                <p>\n                    Users can freely reposition nodes on the canvas. As soon as a node drag finishes, the updated coordinate pair is debounced and synced to Supabase via Row Level Security (RLS) policies.\n                </p>\n\n                <h2>4. Multi-Tenant Branch Sharing &amp; RBAC</h2>\n                <p>\n                    Genealogy is collaborative. Kinship supports multi-tenant branch ownership and granular collaborator invitations through <code>branch_shares</code>:\n                </p>\n                <ul>\n                    <li><strong>Viewer Role:</strong> Allows distant relatives to pan, zoom, inspect member bios, and view photos without altering the lineage structure.</li>\n                    <li><strong>Editor Role:</strong> Empowers trusted family members to add new generations, update dates, attach media, and refine relationships.</li>\n                    <li><strong>Invitation State Machine:</strong> Collaborator requests maintain clean <code>pending</code>, <code>accepted</code>, and <code>declined</code> status transitions.</li>\n                </ul>\n\n                <h2>5. High-Resolution Vector &amp; Document Export</h2>\n                <p>\n                    Families love printing wall charts and archival books. Kinship integrates <code>html2canvas</code> and <code>jspdf</code> to capture the entire active graph viewport:\n                </p>\n                <ul>\n                    <li>Calculates the global bounding box enclosing all family nodes.</li>\n                    <li>Temporarily scales the canvas pixel ratio (2x or 3x) to render ultra-sharp text and photos.</li>\n                    <li>Compiles the output directly into a multi-page PDF or a high-res PNG poster suitable for physical framing.</li>\n                </ul>\n\n                <h2>Technologies &amp; Architecture Overview</h2>\n                <div class=\"article-tags-row\">\n                    <span class=\"article-tag\">React (Vite)</span>\n                    <span class=\"article-tag\">React Flow (@xyflow/react)</span>\n                    <span class=\"article-tag\">Supabase Auth &amp; DB</span>\n                    <span class=\"article-tag\">PostgreSQL RLS</span>\n                    <span class=\"article-tag\">Framer Motion</span>\n                    <span class=\"article-tag\">html2canvas</span>\n                    <span class=\"article-tag\">jspdf</span>\n                    <span class=\"article-tag\">Lucide Icons</span>\n                </div>\n\n                <footer class=\"article-footer\" style=\"display: flex; gap: 1rem; flex-wrap: wrap; margin-top: 2rem;\">\n                    <a href=\"https://familytree-livid.vercel.app\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\">\n                        Open Live App \u2197\n                    </a>\n                    <a href=\"https://github.com/Krishnanand-10/familytree\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"action-btn\" style=\"background-color: var(--bg-card); color: var(--text-primary); border: 1px solid var(--border-color);\">\n                        View on GitHub\n                    </a>\n                </footer>"
};
